class Example {
    void method(String s) {
        // This should be refactored
        if (s.equals("literalValue")) {
            System.out.println("Matched literalValue");
        }
        // This should not be refactored (already safe)
        if ("anotherLiteral".equals(s)) {
            System.out.println("Matched anotherLiteral");
        }
        // This should not be refactored (argument is not a string literal)
        String variable = "someValue";
        if (s.equals(variable)) {
            System.out.println("Matched variable");
        }
    }
}

