negativeExample:
class NegativeExample {
    void method(String s) {
        // Receiver is guaranteed non-null, so no change needed.
        String nonNullString = "fixed";
        if (nonNullString.equals("value")) {
            System.out.println("No change");
        }
        // Argument is not a String literal.
        String otherVar = "test";
        if (s.equals(otherVar)) {
            System.out.println("No change");
        }
        // Already in safe form
        if ("safe".equals(s)) {
            System.out.println("No change");
        }
    }
    // Not a string comparison
    void otherMethod(Object o) {
        if (o.equals(Integer.valueOf(5))) { // Not String.equals
            System.out.println("No change");
        }
    }
}
